struct EmailJob: AsyncJob {
    typealias Payload = Email
    func dequeue(_ ctx: QueueContext, _ p: Email) async throws { try await send(p) }

    func error(_ ctx: QueueContext, _ error: Error, _ p: Email) async throws {
        try await DeadLetter(originalJob: "EmailJob", payload: p,
                             reason: "\(error)").save(on: ctx.application.db)  // park
    }
}
